// Uploads the built artifact to the release bucket.
//
// Credentials are read from the standard AWS environment variables:
// AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and (when applicable)
// AWS_SESSION_TOKEN.  AWS_REGION or AWS_DEFAULT_REGION may override the
// default region for this EU release bucket.
const crypto = require("crypto");
const fs = require("fs");
const https = require("https");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;
const REGION = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || "eu-west-1";

function objectName(version) {
  return `app-${version}.js`;
}

function sha256(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function hmac(key, value, encoding) {
  return crypto.createHmac("sha256", key).update(value).digest(encoding);
}

function signingKey(secret, date) {
  const dateKey = hmac(`AWS4${secret}`, date);
  const regionKey = hmac(dateKey, REGION);
  const serviceKey = hmac(regionKey, "s3");
  return hmac(serviceKey, "aws4_request");
}

function amzDate(now) {
  return now.toISOString().replace(/[:-]|\.\d{3}/g, "");
}

function putObject({ body, key, accessKeyId, secretAccessKey, sessionToken }) {
  const now = new Date();
  const timestamp = amzDate(now);
  const date = timestamp.slice(0, 8);
  const host = `${BUCKET}.s3.${REGION}.amazonaws.com`;
  const path = `/${encodeURIComponent(key).replace(/%2F/g, "/")}`;
  const payloadHash = sha256(body);
  const headers = {
    "content-length": String(body.length),
    "content-type": "application/javascript",
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": timestamp,
  };
  if (sessionToken) headers["x-amz-security-token"] = sessionToken;

  const signedHeaderNames = Object.keys(headers).sort();
  const canonicalHeaders = signedHeaderNames
    .map((name) => `${name}:${headers[name].trim()}\n`)
    .join("");
  const signedHeaders = signedHeaderNames.join(";");
  const canonicalRequest = [
    "PUT", path, "", canonicalHeaders, signedHeaders, payloadHash,
  ].join("\n");
  const credentialScope = `${date}/${REGION}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256", timestamp, credentialScope, sha256(canonicalRequest),
  ].join("\n");
  const signature = hmac(signingKey(secretAccessKey, date), stringToSign, "hex");
  headers.authorization = [
    "AWS4-HMAC-SHA256",
    `Credential=${accessKeyId}/${credentialScope},`,
    `SignedHeaders=${signedHeaders},`,
    `Signature=${signature}`,
  ].join(" ");

  return new Promise((resolve, reject) => {
    const request = https.request({ host, method: "PUT", path, headers }, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        if (response.statusCode >= 200 && response.statusCode < 300) {
          resolve();
        } else {
          reject(new Error(`S3 PUT failed (${response.statusCode}): ${Buffer.concat(chunks).toString("utf8")}`));
        }
      });
    });
    request.on("error", reject);
    request.end(body);
  });
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    throw new Error("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set to upload the release artifact");
  }

  await putObject({
    body,
    key: name,
    accessKeyId,
    secretAccessKey,
    sessionToken: process.env.AWS_SESSION_TOKEN,
  });
  console.log(`uploaded s3://${BUCKET}/${name} (${body.length} bytes)`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
